import{_ as n,a0 as r,w as l,s as h,ao as p,I as i,x as t,a1 as o,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"如何实现ssh无密码登录 | LCTT x X-CMD","titleTemplate":false,"description":"如何实现ssh无密码登录 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何实现ssh无密码登录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何实现ssh无密码登录 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150323 How to enable ssh login without entering password","title":"如何实现ssh无密码登录","tag":"201505","desc":""},"relativePath":"201505/20150323 How to enable ssh login without entering password.md","filePath":"[post].md"}'),d={name:"201505/20150323 How to enable ssh login without entering password.md"};function u(m,s,f,T,g,w){const e=r("Link");return l(),h("div",null,[s[13]||(s[13]=p(`<h1 id="如何实现ssh无密码登录" tabindex="-1">如何实现ssh无密码登录 <a class="header-anchor" href="#如何实现ssh无密码登录" aria-label="Permalink to “如何实现ssh无密码登录”">​</a></h1><p>假设你是hostA上的一个用户&quot;aliceA&quot;，想以用户“aliceB”的身份ssh到hostB上，但又不想输入密码。那么，你可以参考这篇教程实现ssd无密码登录。</p><p>首先，你需要以用户“aliceA”的身份登录到hostA上。</p><p>然后，使用ssh-keygen生成一对rsa公私钥，生成的密钥对会存放在~/.ssh目录下。</p><pre><code>$ ssh-keygen -t rsa
</code></pre><p>接下来，使用下面的命令在目标主机hostB上的aliceB用户目录下创建~/.ssh目录。如果在aliceB@hostB上已经存在.ssh目录，这一步会被略过。</p><pre><code>$ ssh aliceB@hostB mkdir -p .ssh
</code></pre><p>最后，将hostA上用户“aliceA”的公钥拷贝到aliceB@hostB上，来实现无密码ssh。</p><pre><code>$ cat .ssh/id_rsa.pub | ssh aliceB@hostB &#39;cat &gt;&gt; .ssh/authorized_keys&#39;
</code></pre><p>自此以后，从aliceA@hostA上ssh到aliceB@hostB上再也不需要输入密码。（LCTT 译注：上述的创建目录并复制的操作也可以通过一个 ssh-copy-id 命令一步完成：<code>ssh-copy-id -i ~/.ssh/id_rsa.pub aliceB@hostB</code>）</p><h3 id="疑难解答" tabindex="-1">疑难解答 <a class="header-anchor" href="#疑难解答" aria-label="Permalink to “疑难解答”">​</a></h3><ol><li><p>即使在密钥认证生效后，你可能仍然需要输入SSH密码。如果遇到这种情况，请检查系统日志（如/var/log/secure）以查看是否出现下面的异常。</p><p>Authentication refused: bad ownership or modes for file /home/aliceB/.ssh/authorized_keys</p></li></ol><p>在这种情况下，密钥认证的失败是由于~/.ssh/authorized_keys文件的权限或拥有者不正确。一般情况，如果这个文件对除了你之外的所有用户都可读，就会出现这个错误。用下面的方式改变文件的权限以修正错误。</p><pre><code>$ chmod 700 ~/.ssh/authorized_keys 
</code></pre><hr>`,15)),i("p",null,[s[1]||(s[1]=t("via: ",-1)),o(e,{href:"http://xmodulo.com/how-to-enable-ssh-login-without.html"},{default:a(()=>[...s[0]||(s[0]=[t("http://xmodulo.com/how-to-enable-ssh-login-without.html",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=t("作者：",-1)),o(e,{href:"http://xmodulo.com/author/nanni"},{default:a(()=>[...s[2]||(s[2]=[t("Dan Nanni",-1)])]),_:1}),s[6]||(s[6]=t(" 译者：",-1)),o(e,{href:"https://github.com/KayGuoWhu"},{default:a(()=>[...s[3]||(s[3]=[t("KayGuoWhu",-1)])]),_:1}),s[7]||(s[7]=t(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[t("LCTT",-1)])]),_:1}),s[11]||(s[11]=t(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[t("Linux中国",-1)])]),_:1}),s[12]||(s[12]=t(" 荣誉推出",-1))])])}const C=n(d,[["render",u]]);export{_ as __pageData,C as default};
